import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Value-to-weight density ratio of each candidate, normalised by the max ratio among candidates."""
    r = values / np.maximum(weights, 1)
    return r / np.maximum(r.max(), 1e-9)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Candidate value normalised by the largest candidate value (0 if none)."""
    return values / np.maximum(values.max(), 1e-9)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Negative candidate weight relative to the remaining capacity, i.e. the fraction of the free knapsack each item would consume (negated)."""
    return -weights / np.maximum(remaining, 1e-9)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Density discounted by the fraction of the *total* capacity the item consumes."""
    r = values / np.maximum(weights, 1)
    d = r * (1.0 - weights / np.maximum(capacity, 1))
    return d / np.maximum(np.abs(d).max(), 1e-9)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Fraction of the remaining capacity that would still be free after taking each candidate: (remaining - weight) / capacity."""
    return (remaining - weights) / max(capacity, 1)

